// Telemetry test for enrich-orders: generated by otel-as-code v0.24.0 (/otel-test)
// Re-run /otel-test --force to regenerate. /otel-uninstrument removes this file.
//
// What this protects: POST /checkout must keep producing the telemetry listed in
// EXPECTED below. A refactor can rename a handler, drop a middleware or lose the bootstrap flag
// from the start command without breaking any other test. The dashboards and alerts then go
// quiet and nothing fails. This test fails instead, and says which span or metric is missing.
//
// How it works: it starts the service the way production does (node -r ./tracing.js index.js) on a
// free port, with the OpenTelemetry exporter pointed at a small receiver inside this test.
// Nothing leaves the machine and no backend is needed.
//
// Run it: node --test otel.test.cjs
//
// Not covered by this test (this request does not reach them):
//   - orders.describe: no route calls describe()
'use strict';
const test = require('node:test');
const assert = require('node:assert');
const http = require('node:http');
const net = require('node:net');
const { spawn } = require('node:child_process');

// The arguments node starts the service with. When START_SCRIPT names a package.json script, the
// arguments are read from it each run, so a start command that loses its bootstrap flag fails here.
const START_SCRIPT = "start";
const START = startArguments(["-r", "./tracing.js", "index.js"]);
const PORT_ENV = "PORT";
const REQUEST = {"method": "POST", "path": "/checkout", "expectStatus": 200, "json": {"cartId": "c1"}};
const EXPECTED = {
  serverSpan: "POST /checkout",
  spans: ["orders.checkout", "orders.loadLines", "pricing.total"],
  metrics: ["com.example.checkout.order_placed", "com.example.checkout.payment_duration"],
};
const WAIT_MS = 15000;

function startArguments(fallback) {
  if (!START_SCRIPT) return fallback;
  const script = (require('./package.json').scripts || {})[START_SCRIPT];
  assert.ok(typeof script === 'string' && /^node\s+[A-Za-z0-9_.\/@=:+\- ]+$/.test(script.trim()),
    `package.json "scripts.${START_SCRIPT}" is no longer a plain \`node ...\` command (${JSON.stringify(script)}), ` +
    'so this test cannot start the service the way production does. Re-run /otel-test --force.');
  return script.trim().split(/\s+/).slice(1);
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// A minimal OTLP/HTTP receiver: it keeps the name, kind and trace of every span and the name of
// every metric the service exports.
function startReceiver() {
  const seen = { spans: [], metrics: new Set() };
  const server = http.createServer((req, res) => {
    const chunks = [];
    req.on('data', (chunk) => chunks.push(chunk));
    req.on('end', () => {
      try {
        const data = JSON.parse(Buffer.concat(chunks).toString('utf8'));
        for (const rs of data.resourceSpans || []) {
          for (const ss of rs.scopeSpans || []) {
            for (const span of ss.spans || []) seen.spans.push({ name: span.name, kind: span.kind, traceId: span.traceId });
          }
        }
        for (const rm of data.resourceMetrics || []) {
          for (const sm of rm.scopeMetrics || []) {
            for (const metric of sm.metrics || []) seen.metrics.add(metric.name);
          }
        }
      } catch (err) {
        // Not OTLP/JSON: ignore it, the assertions below report what is missing.
      }
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end('{}');
    });
  });
  return new Promise((resolve) => server.listen(0, '127.0.0.1', () => resolve({ server, seen })));
}

function freePort() {
  return new Promise((resolve) => {
    const probe = net.createServer();
    probe.listen(0, '127.0.0.1', () => {
      const { port } = probe.address();
      probe.close(() => resolve(port));
    });
  });
}

const SERVER_KIND = 2; // SPAN_KIND_SERVER in OTLP
const serverSpan = (seen) => seen.spans.find((s) => s.name === EXPECTED.serverSpan && s.kind === SERVER_KIND);
function missing(seen) {
  const out = [];
  const server = serverSpan(seen);
  if (!server) out.push(`the request's own span "${EXPECTED.serverSpan}"`);
  for (const name of EXPECTED.spans) {
    const span = seen.spans.find((s) => s.name === name && (!server || s.traceId === server.traceId));
    if (!span) out.push(`span "${name}"${seen.spans.some((s) => s.name === name) ? ' (it arrived, but outside the request\'s trace)' : ''}`);
  }
  for (const name of EXPECTED.metrics) if (!seen.metrics.has(name)) out.push(`metric "${name}"`);
  return out;
}

test(`${REQUEST.method} ${REQUEST.path} still emits its telemetry`, { timeout: 60000 }, async () => {
  const { server: receiver, seen } = await startReceiver();
  const port = await freePort();
  const env = {};
  for (const [key, value] of Object.entries(process.env)) {
    if (!key.startsWith('OTEL_EXPORTER_OTLP_')) env[key] = value;
  }
  Object.assign(env, {
    [PORT_ENV]: String(port),
    OTEL_EXPORTER_OTLP_ENDPOINT: `http://127.0.0.1:${receiver.address().port}`,
    OTEL_EXPORTER_OTLP_PROTOCOL: 'http/json',
    OTEL_TRACES_EXPORTER: 'otlp',
    OTEL_METRICS_EXPORTER: 'otlp',
    OTEL_LOGS_EXPORTER: 'none',
    OTEL_BSP_SCHEDULE_DELAY: '200',
    OTEL_METRIC_EXPORT_INTERVAL: '500',
    OTEL_METRIC_EXPORT_TIMEOUT: '400',
  });
  let output = '';
  let exited = null;
  const child = spawn(process.execPath, START, { cwd: __dirname, env, stdio: ['ignore', 'pipe', 'pipe'] });
  child.stdout.on('data', (chunk) => { output += chunk; });
  child.stderr.on('data', (chunk) => { output += chunk; });
  child.on('exit', (code, signal) => { exited = { code, signal }; });
  const base = `http://127.0.0.1:${port}`;
  try {
    // Ready when it answers anything at all, even a 404.
    let up = false;
    for (let i = 0; i < 150 && !up && !exited; i++) {
      try { await fetch(base + '/'); up = true; } catch (err) { await sleep(100); }
    }
    assert.ok(up, `the service did not start with: node ${START.join(' ')} (${PORT_ENV}=${port}).\n${output.slice(-2000)}`);

    const init = { method: REQUEST.method };
    if (REQUEST.json !== undefined) {
      init.headers = { 'content-type': 'application/json' };
      init.body = JSON.stringify(REQUEST.json);
    }
    const res = await fetch(base + REQUEST.path, init);
    assert.strictEqual(res.status, REQUEST.expectStatus,
      `${REQUEST.method} ${REQUEST.path} answered ${res.status}, expected ${REQUEST.expectStatus}. This test needs that request to succeed before it can check the telemetry.`);
    await res.arrayBuffer();

    const deadline = Date.now() + WAIT_MS;
    while (missing(seen).length && Date.now() < deadline) await sleep(100);
    const gone = missing(seen);
    if (gone.length) {
      const nothing = seen.spans.length === 0 && seen.metrics.size === 0;
      assert.fail(
        `Missing telemetry for ${REQUEST.method} ${REQUEST.path}:\n  - ${gone.join('\n  - ')}\n` +
        (nothing
          ? `No telemetry arrived at all, so the start command probably no longer loads the OpenTelemetry bootstrap: node ${START.join(' ')}`
          : `Spans that did arrive: ${[...new Set(seen.spans.map((s) => s.name))].sort().join(', ') || '(none)'}\n` +
            `Metrics that did arrive: ${[...seen.metrics].sort().join(', ') || '(none)'}`)
      );
    }
  } finally {
    if (!exited) {
      child.kill('SIGTERM');
      await Promise.race([new Promise((resolve) => child.on('exit', resolve)), sleep(5000)]);
      if (!exited) child.kill('SIGKILL');
    }
    await new Promise((resolve) => receiver.close(resolve));
  }
});
